def build_agent(sandbox):
    # Chassis placed at y=1.2 to ensure ground contact
    chassis_x = 6.9
    chassis_y = 1.2
    chassis = sandbox.add_beam(x=chassis_x, y=chassis_y, width=1.0, height=0.2, density=1.0)
    sandbox.set_fixed_rotation(chassis, True)

    # Add wheels at ground level (y=1.2) with proper radius
    _wheel_joints = []
    for x_off in [-0.4, 0.4]:
        w = sandbox.add_wheel(x=chassis_x + x_off, y=1.2, radius=0.2, density=1.0)
        joint = sandbox.add_joint(chassis, w, (chassis_x + x_off, 1.2), type='pivot')
        # Set motor with appropriate speed and torque
        sandbox.set_motor(joint, motor_speed=-3.2, max_torque=100.0)
        _wheel_joints.append(joint)

    return chassis

def agent_action(sandbox, agent_body, step_count):
    global _wheel_joints
    if not _wheel_joints:
        return

    obj_pos = sandbox.get_object_position()
    if obj_pos is not None:
        object_x = obj_pos[0]
        # Stop motors if chassis is ahead of the object
        if agent_body.position.x > object_x + 1.5:
            for joint in _wheel_joints:
                sandbox.set_motor(joint, motor_speed=0.0, max_torque=100.0)
        else:
            # Drive forward when behind the object
            for joint in _wheel_joints:
                sandbox.set_motor(joint, motor_speed=-3.2, max_torque=100.0)

